import { useEffect, useLayoutEffect, useRef, useState } from 'react';

import type { PlayerStore } from '../player';
import styles from './SharedVideoSurface.module.css';
import { useLocalization } from '../localization/LocalizationProvider';

interface SharedVideoSurfaceProps {
  className?: string;
  nativeControls?: boolean;
  store: PlayerStore;
  title: string;
}

/** The player bar's Video toggle, where focus goes when the minimized panel Video leaves. */
export const videoTheaterToggleId = 'video-theater-toggle';

/**
 * Lets a Video surface inside `root` enter fullscreen. The browser's own controls stay on only
 * while that surface is fullscreen; leaving fullscreen returns the page's controls.
 */
export const useVideoFullscreen = <T extends HTMLElement>() => {
  const root = useRef<T>(null);
  const [nativeControls, setNativeControls] = useState(false);

  useEffect(() => {
    const syncFullscreenState = () => {
      const fullscreenElement = document.fullscreenElement;
      setNativeControls(Boolean(fullscreenElement && root.current?.contains(fullscreenElement)));
    };
    document.addEventListener('fullscreenchange', syncFullscreenState);
    return () => {
      document.removeEventListener('fullscreenchange', syncFullscreenState);
    };
  }, []);

  const enterFullscreen = async () => {
    const container = root.current;
    const media = container?.querySelector('video');
    if (!container || !media) return;

    setNativeControls(true);
    try {
      if (typeof media.requestFullscreen === 'function') {
        await media.requestFullscreen();
      } else if (typeof container.requestFullscreen === 'function') {
        await container.requestFullscreen();
      } else {
        setNativeControls(false);
      }
    } catch {
      setNativeControls(false);
      // Fullscreen is optional; playback and the in-page surface remain available.
    }
  };

  return { enterFullscreen, nativeControls, root };
};

/** Hosts the one store-owned media element on whichever Video surface is visible. */
export const SharedVideoSurface = ({
  className = '',
  nativeControls = false,
  store,
  title
}: SharedVideoSurfaceProps) => {
  const host = useRef<HTMLDivElement>(null);
  const { t } = useLocalization();

  // Layout timing hands the element over before React removes this host, so the browser never sees it leave the document and pause.
  useLayoutEffect(() => {
    if (!host.current) return undefined;
    return store.attachMediaElement(host.current);
  }, [store]);

  useEffect(() => {
    const media = host.current?.querySelector('video');
    if (!media) return undefined;

    media.controls = nativeControls;
    media.tabIndex = nativeControls ? 0 : -1;
    if (nativeControls) {
      media.removeAttribute('aria-hidden');
      media.setAttribute('aria-label', t('video.fullscreen.player_label', { title }));
    } else {
      media.setAttribute('aria-hidden', 'true');
      media.removeAttribute('aria-label');
    }

    return () => {
      media.controls = false;
      media.tabIndex = -1;
      media.setAttribute('aria-hidden', 'true');
      media.removeAttribute('aria-label');
    };
  }, [nativeControls, t, title]);

  return (
    <div
      aria-label={nativeControls ? undefined : t('video.surface.label', { title })}
      className={`${styles.videoSurface} ${className}`}
      ref={host}
      role={nativeControls ? undefined : 'img'}
    />
  );
};
